insert into public.bible_verses (id, book_key, book_name, chapter, verse, content, sort_order)
values
('gen-1-1','gen','창세기',1,1,'태초에 하나님이 천지를 창조하시니라',1),
('gen-1-2','gen','창세기',1,2,'땅이 혼돈하고 공허하며 흑암이 깊음 위에 있고 하나님의 영은 수면 위에 운행하시니라',2),
('gen-1-3','gen','창세기',1,3,'하나님이 이르시되 빛이 있으라 하시니 빛이 있었고',3),
('gen-1-4','gen','창세기',1,4,'빛이 하나님이 보시기에 좋았더라 하나님이 빛과 어둠을 나누사',4),
('gen-1-5','gen','창세기',1,5,'하나님이 빛을 낮이라 부르시고 어둠을 밤이라 부르시니라 저녁이 되고 아침이 되니 이는 첫째 날이니라',5),
('gen-1-6','gen','창세기',1,6,'하나님이 이르시되 물 가운데에 궁창이 있어 물과 물로 나뉘라 하시고',6),
('gen-1-7','gen','창세기',1,7,'하나님이 궁창을 만드사 궁창 아래의 물과 궁창 위의 물로 나뉘게 하시니 그대로 되니라',7),
('gen-1-8','gen','창세기',1,8,'하나님이 궁창을 하늘이라 부르시니라 저녁이 되고 아침이 되니 이는 둘째 날이니라',8),
('gen-1-9','gen','창세기',1,9,'하나님이 이르시되 천하의 물이 한 곳으로 모이고 뭍이 드러나라 하시니 그대로 되니라',9),
('gen-1-10','gen','창세기',1,10,'하나님이 뭍을 땅이라 부르시고 모인 물을 바다라 부르시니 하나님이 보시기에 좋았더라',10),
('gen-1-11','gen','창세기',1,11,'하나님이 이르시되 땅은 풀과 씨 맺는 채소와 각기 종류대로 씨 가진 열매 맺는 나무를 내라 하시니 그대로 되어',11),
('gen-1-12','gen','창세기',1,12,'땅이 풀과 각기 종류대로 씨 맺는 채소와 각기 종류대로 씨 가진 열매 맺는 나무를 내니 하나님이 보시기에 좋았더라',12),
('gen-1-13','gen','창세기',1,13,'저녁이 되고 아침이 되니 이는 셋째 날이니라',13),
('gen-1-14','gen','창세기',1,14,'하나님이 이르시되 하늘의 궁창에 광명체들이 있어 낮과 밤을 나뉘게 하고 그것들로 징조와 계절과 날과 해를 이루게 하라',14),
('gen-1-15','gen','창세기',1,15,'또 광명체들이 하늘의 궁창에 있어 땅을 비추라 하시니 그대로 되니라',15),
('gen-1-16','gen','창세기',1,16,'하나님이 두 큰 광명체를 만드사 큰 광명체로 낮을 주관하게 하시고 작은 광명체로 밤을 주관하게 하시며 또 별들을 만드시고',16),
('gen-1-17','gen','창세기',1,17,'하나님이 그것들을 하늘의 궁창에 두어 땅을 비추게 하시며',17),
('gen-1-18','gen','창세기',1,18,'낮과 밤을 주관하게 하시고 빛과 어둠을 나뉘게 하시니 하나님이 보시기에 좋았더라',18),
('gen-1-19','gen','창세기',1,19,'저녁이 되고 아침이 되니 이는 넷째 날이니라',19),
('gen-1-20','gen','창세기',1,20,'하나님이 이르시되 물들은 생물을 번성하게 하라 땅 위 하늘의 궁창에는 새가 날으라 하시고',20),
('gen-1-21','gen','창세기',1,21,'하나님이 큰 바다 짐승들과 물에서 번성하여 움직이는 모든 생물을 그 종류대로, 날개 있는 모든 새를 그 종류대로 창조하시니 하나님이 보시기에 좋았더라',21),
('gen-1-22','gen','창세기',1,22,'하나님이 그들에게 복을 주시며 이르시되 생육하고 번성하여 여러 바닷물에 충만하라 새들도 땅에 번성하라 하시니라',22),
('gen-1-23','gen','창세기',1,23,'저녁이 되고 아침이 되니 이는 다섯째 날이니라',23),
('gen-1-24','gen','창세기',1,24,'하나님이 이르시되 땅은 생물을 그 종류대로 내되 가축과 기는 것과 땅의 짐승을 종류대로 내라 하시니 그대로 되니라',24),
('gen-1-25','gen','창세기',1,25,'하나님이 땅의 짐승을 그 종류대로, 가축을 그 종류대로, 땅에 기는 모든 것을 그 종류대로 만드시니 하나님이 보시기에 좋았더라',25),
('gen-1-26','gen','창세기',1,26,'하나님이 이르시되 우리의 형상을 따라 우리의 모양대로 우리가 사람을 만들고 그들로 바다의 물고기와 하늘의 새와 가축과 온 땅과 땅에 기는 모든 것을 다스리게 하자 하시고',26),
('gen-1-27','gen','창세기',1,27,'하나님이 자기 형상 곧 하나님의 형상대로 사람을 창조하시되 남자와 여자를 창조하시고',27),
('gen-1-28','gen','창세기',1,28,'하나님이 그들에게 복을 주시며 하나님이 그들에게 이르시되 생육하고 번성하여 땅에 충만하라, 땅을 정복하라, 바다의 물고기와 하늘의 새와 땅에 움직이는 모든 생물을 다스리라 하시니라',28),
('gen-1-29','gen','창세기',1,29,'하나님이 이르시되 내가 온 지면의 씨 맺는 모든 채소와 씨 가진 열매 맺는 모든 나무를 너희에게 주노니 너희의 먹을 거리가 되리라',29),
('gen-1-30','gen','창세기',1,30,'또 땅의 모든 짐승과 하늘의 모든 새와 생명이 있어 땅에 기는 모든 것에게는 내가 모든 푸른 풀을 먹을 거리로 주노라 하시니 그대로 되니라',30),
('gen-1-31','gen','창세기',1,31,'하나님이 지으신 그 모든 것을 보시니 보시기에 심히 좋았더라 저녁이 되고 아침이 되니 이는 여섯째 날이니라',31),
('gen-2-1','gen','창세기',2,1,'천지와 만물이 다 이루어지니라',32),
('gen-2-2','gen','창세기',2,2,'하나님이 그가 하시던 일을 일곱째 날에 마치시니 그가 하시던 모든 일을 그치고 일곱째 날에 안식하시니라',33),
('gen-2-3','gen','창세기',2,3,'하나님이 그 일곱째 날을 복되게 하사 거룩하게 하셨으니 이는 하나님이 그 창조하시며 만드시던 모든 일을 마치시고 그 날에 안식하셨음이니라',34),
('gen-2-4','gen','창세기',2,4,'이것이 천지가 창조될 때에 하늘과 땅의 내력이니 여호와 하나님이 땅과 하늘을 만드시던 날에',35),
('gen-2-5','gen','창세기',2,5,'여호와 하나님이 땅에 비를 내리지 아니하셨고 땅을 갈 사람도 없었으므로 들에는 초목이 아직 없었고 밭에는 채소가 나지 아니하였으며',36),
('gen-2-6','gen','창세기',2,6,'안개만 땅에서 올라와 온 지면을 적셨더라',37),
('gen-2-7','gen','창세기',2,7,'여호와 하나님이 땅의 흙으로 사람을 지으시고 생기를 그 코에 불어넣으시니 사람이 생령이 되니라',38),
('gen-2-8','gen','창세기',2,8,'여호와 하나님이 동방의 에덴에 동산을 창설하시고 그 지으신 사람을 거기 두시니라',39),
('gen-2-9','gen','창세기',2,9,'여호와 하나님이 그 땅에서 보기에 아름답고 먹기에 좋은 나무가 나게 하시니 동산 가운데에는 생명 나무와 선악을 알게 하는 나무도 있더라',40),
('gen-2-10','gen','창세기',2,10,'강이 에덴에서 흘러 나와 동산을 적시고 거기서부터 갈라져 네 근원이 되었으니',41),
('gen-2-11','gen','창세기',2,11,'첫째의 이름은 비손이라 금이 있는 하윌라 온 땅을 둘렀으며',42),
('gen-2-12','gen','창세기',2,12,'그 땅의 금은 순금이요 그 곳에는 베델리엄과 호마노도 있으며',43),
('gen-2-13','gen','창세기',2,13,'둘째 강의 이름은 기혼이라 구스 온 땅을 둘렀고',44),
('gen-2-14','gen','창세기',2,14,'셋째 강의 이름은 힛데겔이라 앗수르 동쪽으로 흘렀으며 넷째 강은 유브라데더라',45),
('gen-2-15','gen','창세기',2,15,'여호와 하나님이 그 사람을 이끌어 에덴 동산에 두어 그것을 경작하며 지키게 하시고',46),
('gen-2-16','gen','창세기',2,16,'여호와 하나님이 그 사람에게 명하여 이르시되 동산 각종 나무의 열매는 네가 임의로 먹되',47),
('gen-2-17','gen','창세기',2,17,'선악을 알게 하는 나무의 열매는 먹지 말라 네가 먹는 날에는 반드시 죽으리라 하시니라',48),
('gen-2-18','gen','창세기',2,18,'여호와 하나님이 이르시되 사람이 혼자 사는 것이 좋지 아니하니 내가 그를 위하여 돕는 배필을 지으리라 하시니라',49),
('gen-2-19','gen','창세기',2,19,'여호와 하나님이 흙으로 각종 들짐승과 공중의 각종 새를 지으시고 아담이 무엇이라고 부르나 보시려고 그것들을 그에게로 이끌어 가시니 아담이 각 생물을 부르는 것이 곧 그 이름이 되었더라',50),
('gen-2-20','gen','창세기',2,20,'아담이 모든 가축과 공중의 새와 들의 모든 짐승에게 이름을 주니라 아담이 돕는 배필이 없으므로',51),
('gen-2-21','gen','창세기',2,21,'여호와 하나님이 아담을 깊이 잠들게 하시니 잠들매 그가 그 갈빗대 하나를 취하고 살로 대신 채우시고',52),
('gen-2-22','gen','창세기',2,22,'여호와 하나님이 아담에게서 취하신 그 갈빗대로 여자를 만드시고 그를 아담에게로 이끌어 오시니',53),
('gen-2-23','gen','창세기',2,23,'아담이 이르되 이는 내 뼈 중의 뼈요 살 중의 살이라 이것을 남자에게서 취하였은즉 여자라 부르리라 하니라',54),
('gen-2-24','gen','창세기',2,24,'이러므로 남자가 부모를 떠나 그의 아내와 합하여 둘이 한 몸을 이룰지로다',55),
('gen-2-25','gen','창세기',2,25,'아담과 그의 아내 두 사람이 벌거벗었으나 부끄러워하지 아니하니라',56),
('gen-3-1','gen','창세기',3,1,'그런데 뱀은 여호와 하나님이 지으신 들짐승 중에 가장 간교하니라 뱀이 여자에게 물어 이르되 하나님이 참으로 너희에게 동산 모든 나무의 열매를 먹지 말라 하시더냐',57),
('gen-3-2','gen','창세기',3,2,'여자가 뱀에게 말하되 동산 나무의 열매를 우리가 먹을 수 있으나',58),
('gen-3-3','gen','창세기',3,3,'동산 중앙에 있는 나무의 열매는 하나님의 말씀에 너희는 먹지도 말고 만지지도 말라 너희가 죽을까 하노라 하셨느니라',59),
('gen-3-4','gen','창세기',3,4,'뱀이 여자에게 이르되 너희가 결코 죽지 아니하리라',60),
('gen-3-5','gen','창세기',3,5,'너희가 그것을 먹는 날에는 너희 눈이 밝아져 하나님과 같이 되어 선악을 알 줄 하나님이 아심이니라',61),
('gen-3-6','gen','창세기',3,6,'여자가 그 나무를 본즉 먹음직도 하고 보암직도 하고 지혜롭게 할 만큼 탐스럽기도 한 나무인지라 여자가 그 열매를 따먹고 자기와 함께 있는 남편에게도 주매 그도 먹은지라',62),
('gen-3-7','gen','창세기',3,7,'이에 그들의 눈이 밝아져 자기들이 벗은 줄을 알고 무화과나무 잎을 엮어 치마로 삼았더라',63),
('gen-3-8','gen','창세기',3,8,'그들이 그 날 바람이 불 때 동산에 거니시는 여호와 하나님의 소리를 듣고 아담과 그의 아내가 여호와 하나님의 낯을 피하여 동산 나무 사이에 숨은지라',64),
('gen-3-9','gen','창세기',3,9,'여호와 하나님이 아담을 부르시며 그에게 이르시되 네가 어디 있느냐',65),
('gen-3-10','gen','창세기',3,10,'이르되 내가 동산에서 하나님의 소리를 듣고 내가 벗었으므로 두려워하여 숨었나이다',66),
('gen-3-11','gen','창세기',3,11,'이르시되 누가 너의 벗었음을 네게 알렸느냐 내가 네게 먹지 말라 명한 그 나무 열매를 네가 먹었느냐',67),
('gen-3-12','gen','창세기',3,12,'아담이 이르되 하나님이 주셔서 나와 함께 있게 하신 여자 그가 그 나무 열매를 내게 주므로 내가 먹었나이다',68),
('gen-3-13','gen','창세기',3,13,'여호와 하나님이 여자에게 이르시되 네가 어찌하여 이렇게 하였느냐 여자가 이르되 뱀이 나를 꾀므로 내가 먹었나이다',69),
('gen-3-14','gen','창세기',3,14,'여호와 하나님이 뱀에게 이르시되 네가 이렇게 하였으니 네가 모든 가축과 들의 모든 짐승보다 더욱 저주를 받아 배로 다니고 살아 있는 동안 흙을 먹을지니라',70),
('gen-3-15','gen','창세기',3,15,'내가 너로 여자와 원수가 되게 하고 네 후손도 여자의 후손과 원수가 되게 하리니 여자의 후손은 네 머리를 상하게 할 것이요 너는 그의 발꿈치를 상하게 할 것이니라 하시고',71),
('gen-3-16','gen','창세기',3,16,'또 여자에게 이르시되 내가 네게 임신하는 고통을 크게 더하리니 네가 수고하고 자식을 낳을 것이며 너는 남편을 원하고 남편은 너를 다스릴 것이니라 하시고',72),
('gen-3-17','gen','창세기',3,17,'아담에게 이르시되 네가 네 아내의 말을 듣고 내가 네게 먹지 말라 한 나무의 열매를 먹었은즉 땅은 너로 말미암아 저주를 받고 너는 네 평생에 수고하여야 그 소산을 먹으리라',73),
('gen-3-18','gen','창세기',3,18,'땅이 네게 가시덤불과 엉겅퀴를 낼 것이라 네가 먹을 것은 밭의 채소인즉',74),
('gen-3-19','gen','창세기',3,19,'네가 흙으로 돌아갈 때까지 얼굴에 땀을 흘려야 먹을 것을 먹으리니 네가 그것에서 취함을 입었음이라 너는 흙이니 흙으로 돌아갈 것이니라 하시니라',75),
